export const posScript = (u: (p: string) => string, j: (v: unknown) => string, h: (v: unknown) => string, a: Record<string, unknown> = {}, x: string[] = []): string => `<script>
document.addEventListener('DOMContentLoaded', function () {

/* =====================================================================
 * 1. CONFIGURATION CONSTANTS (server-rendered, read-only for this page)
 * ===================================================================== */
const CAN_OVERRIDE_DISCOUNT = ${x[0]};
const CAN_MANUAL_OVERRIDE_RATE = ${x[1]};
const MAX_DISCOUNT = ${x[2]};
const DEFAULT_PRICE_LIST_ID = ${x[3]};
const PRESELECT_CUSTOMER_ID = ${x[4]};
const ORDER_VIEW_URL = ${j(u('modules/orders/view.php'))};
const TAGS_PRINT_URL = ${j(u('modules/barcode/tags_print.php'))};
const API = {
  customerSearch: ${j(u('api/customers_search.php'))},
  customerSummary: ${j(u('api/customer_pos_summary.php'))},
  garments: ${j(u('api/garments_for_pos.php'))},
  rate: ${j(u('api/pos_get_rate.php'))},
  submit: ${j(u('modules/pos/submit.php'))},
  newOrderToken: ${j(u('api/pos_new_token.php'))},
};
const PAYMENT_TYPES = ${x[5]};
const FIRST_SERVICE_ID = ${x[6]};
const FIRST_CATEGORY_ID = ${x[8]};

/* =====================================================================
 * 2. STATE VARIABLES
 * (all mutable page state lives here — nothing implicit, nothing global
 * outside this DOMContentLoaded closure)
 * ===================================================================== */
let selectedCustomer = null;
let selectedPriceListId = DEFAULT_PRICE_LIST_ID;
let activeServiceId = FIRST_SERVICE_ID;
// Rahul: a fresh New Order left Category unselected until tapped, so the garment grid showed
// nothing on load -- same gap as the Android app had (fixed there first), ported here. Service
// was already correctly defaulting via FIRST_SERVICE_ID above; Category needed the same
// treatment.
let activeCategoryId = FIRST_CATEGORY_ID;
let cart = [];                 // array of line-item objects shown in the Order Items cart
let pendingGarment = null;      // the garment currently open in the Add/Edit Garment modal
let agCurrentRate = null;       // last rate response fetched for pendingGarment (server-authoritative)
// True only while the staff member has explicitly activated Manual Rate Override for the
// CURRENT modal session, AND is authorized (CAN_MANUAL_OVERRIDE_RATE). This is purely a UX-gate
// flag — it grants no authority on its own; the server independently re-verifies authorization
// via Auth::can('pos.manual_rate_override') on the actual session at submit time, never trusting
// this flag or anything else the client sends. Reset to false on every fresh modal open.
let manualOverrideActive = false;
let manualOverrideConfiguredRate = null; // the ORIGINAL configured rate, if any, preserved for the audit note shown in the UI
let editingCartIndex = null;    // null = adding a new line; number = editing cart[index] in place
let submitting = false;         // guards against a double "Confirm & Save" click
// The single-use anti-replay token for THIS order attempt. Starts as the value minted when this
// page was rendered; once consumed by a successful save, resetPosForNextOrder() fetches a fresh
// one from api/pos_new_token.php before the form becomes usable again for the NEXT order — this
// is what lets "same form resubmitted" stay blocked while "new order, same customer" is allowed.
let orderToken = ${x[7]};
let searchDebounceTimer = null;
let garmentSearchDebounceTimer = null;
let dueDateManuallyEdited = false; // once the staff member edits Due Date directly, stop auto-suggesting
let walletAvailableAmount = 0;     // numeric wallet/advance balance for the selected customer (fmt() text alone isn't usable for math)
let walletManuallyEdited = false;  // true once staff types directly into the Wallet Amount field
let paymentManuallyEdited = false; // true once staff types directly into the first (auto-managed) payment line

/* =====================================================================
 * 3. DOM REFERENCES
 * (looked up once; every element referenced from more than one function
 * lives here so a typo or renamed id fails fast, in one place)
 * ===================================================================== */
const dom = {
  customerSearch: document.getElementById('customerSearch'),
  customerResults: document.getElementById('customerResults'),
  customerDetails: document.getElementById('customerDetails'),
  clearCustomerBtn: document.getElementById('clearCustomerBtn'),
  cdName: document.getElementById('cdName'),
  cdMobile: document.getElementById('cdMobile'),
  cdAddress: document.getElementById('cdAddress'),
  cdPriceList: document.getElementById('cdPriceList'),
  cdOutstanding: document.getElementById('cdOutstanding'),
  cdWallet: document.getElementById('cdWallet'),
  walletAvailable: document.getElementById('walletAvailable'),
  homeDelivery: document.getElementById('homeDelivery'),
  deliveryChargeWrap: document.getElementById('deliveryChargeWrap'),
  deliveryCharge: document.getElementById('deliveryCharge'),

  garmentGrid: document.getElementById('garmentGrid'),
  garmentSearch: document.getElementById('garmentSearch'),

  cartBody: document.getElementById('cartBody'),
  urgentLevel: document.getElementById('urgentLevel'),
  discountType: document.getElementById('discountType'),
  discountValue: document.getElementById('discountValue'),
  dueDate: document.getElementById('dueDate'),
  packagingPreference: document.getElementById('packagingPreference'),
  dueDateHint: document.getElementById('dueDateHint'),
  dueTime: document.getElementById('dueTime'),
  orderNotes: document.getElementById('orderNotes'),

  sumSubtotal: document.getElementById('sumSubtotal'),
  sumDiscount: document.getElementById('sumDiscount'),
  sumUrgent: document.getElementById('sumUrgent'),
  sumDelivery: document.getElementById('sumDelivery'),
  sumTax: document.getElementById('sumTax'),
  sumQuantity: document.getElementById('sumQuantity'),
  sumPieces: document.getElementById('sumPieces'),
  sumGrandTotal: document.getElementById('sumGrandTotal'),
  sumPaid: document.getElementById('sumPaid'),
  sumDue: document.getElementById('sumDue'),

  useWallet: document.getElementById('useWallet'),
  walletAmount: document.getElementById('walletAmount'),
  paymentRows: document.getElementById('paymentRows'),
  addPaymentRowBtn: document.getElementById('addPaymentRow'),
  placeOrderBtn: document.getElementById('placeOrderBtn'),

  // Add/Edit Garment modal
  agModalTitle: document.querySelector('#addGarmentModal .modal-title'),
  agService: document.getElementById('agService'),
  agBillingUnitDisplay: document.getElementById('agBillingUnitDisplay'),
  agQtyWrap: document.getElementById('agQtyWrap'),
  agWeightWrap: document.getElementById('agWeightWrap'),
  agQuantity: document.getElementById('agQuantity'),
  agQtyMinus: document.getElementById('agQtyMinus'),
  agQtyPlus: document.getElementById('agQtyPlus'),
  agWeight: document.getElementById('agWeight'),
  agConfiguredRate: document.getElementById('agConfiguredRate'),
  agRateOverride: document.getElementById('agRateOverride'),
  agManualOverrideOfferRow: document.getElementById('agManualOverrideOfferRow'),
  agEnableManualOverrideBtn: document.getElementById('agEnableManualOverrideBtn'),
  agManualOverrideUnauthorized: document.getElementById('agManualOverrideUnauthorized'),
  agManualOverrideActive: document.getElementById('agManualOverrideActive'),
  agManualOverrideConfiguredNote: document.getElementById('agManualOverrideConfiguredNote'),
  agCancelManualOverrideBtn: document.getElementById('agCancelManualOverrideBtn'),
  agTaxDisplay: document.getElementById('agTaxDisplay'),
  agLineTotalDisplay: document.getElementById('agLineTotalDisplay'),
  agBrand: document.getElementById('agBrand'),
  agColor: document.getElementById('agColor'),
  agRemarks: document.getElementById('agRemarks'),
  agError: document.getElementById('agError'),
  agAddBtn: document.getElementById('agAddBtn'),

  confirmBody: document.getElementById('confirmBody'),
  confirmSaveBtn: document.getElementById('confirmSaveBtn'),
};

/* =====================================================================
 * 4. BOOTSTRAP MODAL INITIALIZATION
 * Safe here: this whole block only runs after DOMContentLoaded, which
 * fires after every <script> tag in the document — including footer.php's
 * bootstrap.bundle.min.js — has already executed. \`bootstrap\` is
 * guaranteed to exist by this point.
 * ===================================================================== */
const agModal = new bootstrap.Modal(document.getElementById('addGarmentModal'));
const confirmModalEl = document.getElementById('confirmModal');
const confirmModal = new bootstrap.Modal(confirmModalEl);

// ROOT CAUSE (real one, found by tracing Bootstrap's own lifecycle, not just re-removing the
// backdrop): confirmModal.hide() is animated. Bootstrap's OWN internal bookkeeping — its
// _isShown/_isTransitioning flags, its focus trap, its final backdrop teardown — only resolves
// when its CSS transition genuinely finishes, at which point Bootstrap fires 'hidden.bs.modal'
// itself. The PREVIOUS fix here manually ripped out .modal-backdrop and body.modal-open
// immediately after calling hide() — while Bootstrap's own transition was very likely still in
// flight. That desynced Bootstrap's internal state from the DOM: the backdrop LOOKED gone, but
// Bootstrap's focus trap (which listens for focusin on the whole document and redirects focus
// back into the modal while it still believes itself "shown") kept running, silently stealing
// focus/interaction back from the customer search box, garment cards, and the next Confirm/Place
// Order attempt — matching exactly what was reported: visually clean, but dead to input, and the
// next order's confirm modal failing to reopen (Bootstrap's show() no-ops while it still thinks
// a transition is in progress). The fix is to stop fighting Bootstrap's lifecycle: call hide(),
// then wait for Bootstrap's OWN 'hidden.bs.modal' event — proof its internal state has genuinely,
// completely resolved — before running anything else. A short safety timeout is kept ONLY as a
// last-resort fallback in case that event is somehow never fired, so this can never hang forever.
function closeConfirmModalThenRun(callback) {
  let done = false;
  function finish() {
    if (done) return;
    done = true;
    confirmModalEl.removeEventListener('hidden.bs.modal', finish);
    callback();
  }
  confirmModalEl.addEventListener('hidden.bs.modal', finish, { once: true });
  confirmModal.hide();
  // Fallback ONLY — if Bootstrap's own event genuinely never fires (should not happen in normal
  // operation), a small manual nudge is warranted here specifically, since reaching this path
  // means something already went wrong with Bootstrap's own lifecycle. The normal, expected path
  // above never touches the DOM directly, precisely to avoid re-introducing the same interference
  // that caused this bug in the first place.
  setTimeout(function () {
    if (done) return;
    document.querySelectorAll('.modal-backdrop').forEach(function (el) { el.remove(); });
    document.body.classList.remove('modal-open');
    document.body.style.removeProperty('overflow');
    document.body.style.removeProperty('padding-right');
    finish();
  }, 800);
}

/* =====================================================================
 * 5. EVENT BINDING
 * ===================================================================== */
dom.customerSearch.addEventListener('input', onCustomerSearchInput);
dom.customerSearch.addEventListener('keydown', function (e) {
  if (e.key === 'Escape') dom.customerResults.classList.add('d-none');
});
dom.clearCustomerBtn.addEventListener('click', clearCustomer);
dom.homeDelivery.addEventListener('change', function () { toggleDeliveryCharge(); recomputeSummary(); });

// Due Date: auto-suggested from the selected urgent level's configured day_offset (never a
// silent/hidden override — the suggestion is visible, editable, and only ever applied before
// the staff member has touched the field themselves).
dom.urgentLevel.addEventListener('change', suggestDueDate);
dom.dueDate.addEventListener('input', function () { dueDateManuallyEdited = true; });

document.querySelectorAll('.svc-tab').forEach(btn => btn.addEventListener('click', onServiceTabClick));
document.querySelectorAll('.cat-tab').forEach(btn => btn.addEventListener('click', onCategoryTabClick));

// Rahul: visually select the default Service/Category tabs and load the grid immediately, so
// the page isn't just internally defaulted (activeServiceId/activeCategoryId) while LOOKING
// like nothing is selected -- matches the toggle logic onServiceTabClick/onCategoryTabClick
// themselves use, just applied once on load instead of waiting for a click.
if (FIRST_SERVICE_ID) {
  const firstSvcTab = document.querySelector('.svc-tab[data-id="' + FIRST_SERVICE_ID + '"]');
  if (firstSvcTab) firstSvcTab.classList.add('btn-primary');
}
if (FIRST_CATEGORY_ID) {
  const firstCatTab = document.querySelector('.cat-tab[data-id="' + FIRST_CATEGORY_ID + '"]');
  if (firstCatTab) { firstCatTab.classList.remove('btn-outline-secondary'); firstCatTab.classList.add('btn-secondary'); }
  loadGarments();
}
// Rahul: Due Date stayed blank until the staff member actively touched the Urgent Level
// dropdown -- suggestDueDate() only ever ran from its own 'change' listener. The "Normal"
// <option> (blank value, data-day-offset from the default_due_days setting) is already the
// browser's default selection on a fresh page, so calling this once here needs no further
// logic change -- it reads the already-correct default selection, same as any user-triggered
// call would.
suggestDueDate();
dom.garmentSearch.addEventListener('input', function () {
  clearTimeout(garmentSearchDebounceTimer);
  garmentSearchDebounceTimer = setTimeout(loadGarments, 300);
});

dom.agService.addEventListener('change', fetchAgRate);
dom.agQtyMinus.addEventListener('click', function () { stepQuantity(-1); });
dom.agQtyPlus.addEventListener('click', function () { stepQuantity(1); });
dom.agQuantity.addEventListener('input', recomputeAgLineTotal);
dom.agWeight.addEventListener('input', recomputeAgLineTotal);
dom.agRateOverride.addEventListener('input', recomputeAgLineTotal);
dom.agAddBtn.addEventListener('click', onAddOrUpdateCartItem);
// Explicitly wrapped (not passed directly) — addEventListener would otherwise pass the DOM
// click Event as the first argument, which onEnableManualOverrideClick's preserveRate parameter
// would read as truthy, wrongly skipping the rate-clear on every ordinary click.
dom.agEnableManualOverrideBtn.addEventListener('click', function () { onEnableManualOverrideClick(false); });
dom.agCancelManualOverrideBtn.addEventListener('click', onCancelManualOverrideClick);

['discountType', 'discountValue', 'urgentLevel', 'deliveryCharge'].forEach(function (id) {
  dom[id].addEventListener('input', recomputeSummary);
  dom[id].addEventListener('change', recomputeSummary);
});

dom.addPaymentRowBtn.addEventListener('click', function () { addPaymentRow(); });
dom.useWallet.addEventListener('change', function () {
  dom.walletAmount.classList.toggle('d-none', !dom.useWallet.checked);
  if (dom.useWallet.checked) {
    // Fresh auto-suggestion every time the checkbox is (re-)enabled — start from a clean slate
    // rather than whatever stale manual edits were left over from a previous toggle.
    walletManuallyEdited = false;
    paymentManuallyEdited = false;
  } else {
    dom.walletAmount.value = '';
  }
  recomputeSummary(); // grand total may be stale if this is the very first interaction on the page
});
dom.walletAmount.addEventListener('input', function () {
  walletManuallyEdited = true;
  updatePaymentSummary();
});

dom.placeOrderBtn.addEventListener('click', openConfirmModal);
dom.confirmSaveBtn.addEventListener('click', submitOrder);

/* =====================================================================
 * 6. FUNCTIONS
 * ===================================================================== */

// ---------- Customer selection ----------
function onCustomerSearchInput() {
  clearTimeout(searchDebounceTimer);
  const q = dom.customerSearch.value.trim();
  if (q.length < 2) { dom.customerResults.classList.add('d-none'); return; }
  searchDebounceTimer = setTimeout(function () {
    fetch(API.customerSearch + '?q=' + encodeURIComponent(q))
      .then(r => r.json())
      .then(function (data) {
        dom.customerResults.innerHTML = '';
        (data.results || []).forEach(function (c) {
          const div = document.createElement('div');
          div.className = 'item';
          // Shows Name/Mobile/Address/Customer Code — customers_search.php already returns
          // address/area/city/state/pincode (fixed earlier), this just displays them; the
          // customer summary panel after selection already showed address (see cdAddress
          // below), only this compact search-result row was missing it.
          const addressParts = [c.address, c.area, c.city, c.state, c.pincode].filter(p => p && String(p).trim());
          const addressLine = addressParts.length ? addressParts.join(', ') : '';
          div.innerHTML = '<div class="fw-bold">' + escapeHtml(c.title + ' ' + c.full_name) + '</div>'
            + '<div class="small text-muted">Mobile: ' + escapeHtml(c.mobile || '—') + '</div>'
            + (addressLine ? '<div class="small text-muted">Address: ' + escapeHtml(addressLine) + '</div>' : '')
            + '<div class="small text-muted">Code: ' + escapeHtml(c.customer_code || '—') + '</div>';
          div.addEventListener('click', function () { selectCustomer(c.id); });
          dom.customerResults.appendChild(div);
        });
        dom.customerResults.classList.toggle('d-none', (data.results || []).length === 0);
      })
      .catch(function () { dom.customerResults.classList.add('d-none'); });
  }, 300);
}

function selectCustomer(id) {
  fetch(API.customerSummary + '?customer_id=' + id)
    .then(r => r.json())
    .then(function (data) {
      if (!data.success) { alert(data.message || 'Could not load customer.'); return; }
      selectedCustomer = data.customer;
      selectedPriceListId = data.price_list_id;
      dom.customerResults.classList.add('d-none');
      dom.customerSearch.value = '';
      dom.customerDetails.classList.remove('d-none');
      dom.cdName.textContent = data.customer.name;
      dom.cdMobile.textContent = data.customer.mobile;
      dom.cdAddress.textContent = data.customer.address || '—';
      dom.cdPriceList.textContent = data.price_list_name;
      dom.cdOutstanding.textContent = fmt(data.outstanding);
      dom.cdWallet.textContent = fmt(data.wallet_balance);
      dom.walletAvailable.textContent = fmt(data.wallet_balance);
      walletAvailableAmount = parseFloat(data.wallet_balance) || 0;
      walletManuallyEdited = false;
      paymentManuallyEdited = false;
      dom.homeDelivery.checked = !!data.customer.home_delivery;
      toggleDeliveryCharge();
      recomputeSummary();
      if (activeCategoryId) loadGarments();
    })
    .catch(function () { alert('Could not reach the server to load this customer. Please try again.'); });
}

function clearCustomer() {
  selectedCustomer = null;
  selectedPriceListId = DEFAULT_PRICE_LIST_ID;
  walletAvailableAmount = 0;
  walletManuallyEdited = false;
  paymentManuallyEdited = false;
  dom.customerDetails.classList.add('d-none');
}

// ---------- Service / Category tabs + garment grid ----------
function onServiceTabClick() {
  document.querySelectorAll('.svc-tab').forEach(b => b.classList.remove('btn-primary'));
  this.classList.add('btn-primary');
  activeServiceId = parseInt(this.dataset.id, 10);
  loadGarments();
}

function onCategoryTabClick() {
  // Root cause of the "active category text invisible" bug: the previous code only ever ADDED
  // btn-secondary to the clicked button, never REMOVING btn-outline-secondary first — every
  // category button starts with btn-outline-secondary already present (see the PHP-rendered
  // markup below), so the active button ended up with BOTH variant classes simultaneously.
  // Bootstrap's .btn-secondary and .btn-outline-secondary have conflicting color/background
  // rules; with both classes present, the cascade can resolve background-color and color from
  // DIFFERENT rules, producing a dark box with near-invisible text. Toggling the pair properly
  // (exactly one variant class present at all times) is the correct, generic fix — applies to
  // every category, not just whichever one happens to be active.
  document.querySelectorAll('.cat-tab').forEach(function (b) {
    b.classList.remove('btn-secondary');
    b.classList.add('btn-outline-secondary');
  });
  this.classList.remove('btn-outline-secondary');
  this.classList.add('btn-secondary');
  activeCategoryId = parseInt(this.dataset.id, 10);
  loadGarments();
}

function loadGarments() {
  if (!activeCategoryId) {
    dom.garmentGrid.innerHTML = '<p class="text-muted">Select a category to view garments.</p>';
    return;
  }
  const q = dom.garmentSearch.value.trim();
  const params = new URLSearchParams({
    category_id: activeCategoryId, service_id: activeServiceId || '', q,
    price_list_id: selectedPriceListId || '',
  });
  fetch(API.garments + '?' + params.toString())
    .then(r => r.json())
    .then(function (data) {
      dom.garmentGrid.innerHTML = '';
      const garments = data.garments || [];
      garments.forEach(function (g) {
        const div = document.createElement('div');
        div.className = 'garment-card';
        div.innerHTML = (g.image ? '<img src="' + g.image + '">' : '<div style="height:60px;display:flex;align-items:center;justify-content:center;"><i class="fa-solid fa-shirt text-muted"></i></div>')
          + '<div class="g-name">' + escapeHtml(g.name) + '</div>'
          + (g.sku ? '<div class="text-muted" style="font-size:11px;">' + escapeHtml(g.sku) + '</div>' : '')
          + (g.display_has_price && Number(g.display_rate) === 0 ? '<div class="g-rate" style="color:#b45309;">Price at counter</div>' : g.display_has_price ? '<div class="g-rate">from ' + fmt(g.display_rate) + (g.billing_unit === 'weight' ? ' / kg' : ' / pc') + '</div>' : '<div class="g-nopricing">No price configured</div>');
        div.addEventListener('click', function () { openGarmentModal(g, null); });
        dom.garmentGrid.appendChild(div);
      });
      if (garments.length === 0) dom.garmentGrid.innerHTML = '<p class="text-muted">No garments found.</p>';
    })
    .catch(function () {
      dom.garmentGrid.innerHTML = '<p class="text-danger">Could not load garments. Please check your connection and try again.</p>';
    });
}

// ---------- Add / Edit Garment modal ----------
// editIndex: null when adding a brand-new cart line; a cart array index when editing an
// existing line in place (requirement: edit without delete+recreate).
function openGarmentModal(g, editIndex) {
  if (!selectedCustomer) { alert('Please select a customer first.'); return; }

  editingCartIndex = editIndex;
  pendingGarment = g;

  dom.agModalTitle.innerHTML = (editIndex === null ? 'Add Garment: ' : 'Edit Garment: ')
    + '<span id="agGarmentName">' + escapeHtml(g.name) + '</span>';

  dom.agAddBtn.textContent = editIndex === null ? 'Add to Order' : 'Update Order';

  if (editIndex !== null) {
    const item = cart[editIndex];
    dom.agService.value = item.service_id;
    dom.agQuantity.value = item.billing_unit === 'weight' ? 1 : item.quantity;
    dom.agWeight.value = item.billing_unit === 'weight' ? item.weight : '';
    dom.agBrand.value = item.brand_id || '';
    dom.agColor.value = item.color_id || '';
    dom.agRemarks.value = item.remarks || '';
    document.querySelectorAll('.ag-defect').forEach(function (cb) {
      cb.checked = item.defect_ids.indexOf(parseInt(cb.value, 10)) !== -1;
    });
  } else {
    // The service tab the staff member is actively browsing under is a far stronger signal of
    // intent than the garment's own static default_service_id — clicking "Waist Coat" while on
    // the Laundry tab means "add this under Laundry", full stop, regardless of what Waist Coat's
    // stored default happens to be. default_service_id is only a fallback for the (practically
    // unreachable, since a tab is always active from page load onward) case where no tab context
    // exists at all.
    dom.agService.value = activeServiceId || g.default_service_id;
    dom.agQuantity.value = 1;
    dom.agWeight.value = '';
    dom.agBrand.value = '';
    dom.agColor.value = '';
    dom.agRemarks.value = '';
    document.querySelectorAll('.ag-defect').forEach(cb => cb.checked = false);
  }

  dom.agError.classList.add('d-none');
  // Manual Rate Override must NEVER leak from one garment to the next — reset to the hidden/
  // inactive state before the async fetch even starts, same reasoning as the field-lock below.
  resetManualOverrideUI();
  // Lock every pricing field the instant the modal opens, before the async price fetch even
  // starts — closes the brief window where a PREVIOUS garment's enabled fields/stale values
  // could still be visible while this garment's fetch is in flight. fetchAgRate() below
  // re-enables exactly what applies once it resolves, per its own success/failure branches.
  dom.agWeight.disabled = true;
  dom.agQuantity.disabled = true;
  dom.agQtyMinus.disabled = true;
  dom.agQtyPlus.disabled = true;
  dom.agRateOverride.disabled = true;
  dom.agConfiguredRate.disabled = true;
  dom.agTaxDisplay.disabled = true;
  dom.agLineTotalDisplay.disabled = true;
  dom.agAddBtn.disabled = true;
  // fetchAgRate() sets agRateOverride to the configured rate; when editing, restore the
  // previously-saved override AFTER the fetch resolves so it isn't clobbered. If the cart line
  // being edited was itself saved as a Manual Rate Override, fetchAgRate() also re-activates the
  // override UI once it resolves (see the editingCartIndex check in both of its branches) —
  // rather than silently reverting an authorized override back to a locked/offer state just
  // because the modal was reopened to edit it.
  fetchAgRate(editIndex !== null ? cart[editIndex].rate_override : null);
  agModal.show();
}

function stepQuantity(delta) {
  if (dom.agQuantity.disabled) return; // defense in depth, matching the same pattern used for Add to Order
  const current = parseInt(dom.agQuantity.value, 10) || 1;
  const next = Math.max(1, current + delta);
  dom.agQuantity.value = next;
  recomputeAgLineTotal();
}

// Fetches the SERVER-AUTHORITATIVE rate AND billing_unit for the pending garment/service/
// price-list combination. billing_unit is a SERVICE-level business rule (Dry Cleaning = piece,
// Laundry = weight, etc.) — never a manual toggle; the qty/weight input shown is locked to
// whatever the server says. restoreOverride (optional) re-applies a previously-entered rate
// override when editing an existing cart line, instead of resetting to the configured rate.
let agRateRequestSeq = 0; // increments on every fetchAgRate() call; a response only applies if
                           // it's still the MOST RECENT request — closes a real race condition
                           // where a slow, earlier garment's response could arrive after a later,
                           // faster garment's response and overwrite it with stale data.

function fetchAgRate(restoreOverride) {
  if (!pendingGarment) return;
  const serviceId = dom.agService.value;
  const requestId = ++agRateRequestSeq;
  const params = new URLSearchParams({
    garment_id: pendingGarment.id, service_id: serviceId, price_list_id: selectedPriceListId || '',
  });
  fetch(API.rate + '?' + params.toString())
    .then(r => r.json())
    .then(function (data) {
      if (requestId !== agRateRequestSeq) return; // a newer request has since been made; discard
      if (!data.success) {
        agCurrentRate = null;
        dom.agError.textContent = data.message || 'Price not configured for this garment/service.';
        dom.agError.classList.remove('d-none');
        // Even on failure, billing_unit is now always returned — the modal must still show the
        // CORRECT unit (Weight/Piece) for the selected service, never leftover state from
        // whatever garment happened to be open before this one.
        const isWeight = data.billing_unit === 'weight';
        dom.agBillingUnitDisplay.value = isWeight ? 'Weight (KG)' : 'Quantity (Pieces)';
        dom.agQtyWrap.classList.toggle('d-none', isWeight);
        dom.agWeightWrap.classList.toggle('d-none', !isWeight);
        dom.agConfiguredRate.value = '';
        dom.agRateOverride.value = '';
        dom.agTaxDisplay.value = '';
        dom.agLineTotalDisplay.value = '';
        // UX-only: gray out and lock every pricing-related input while there is genuinely no
        // price to act on — purely visual/interaction state, no validation logic lives here.
        // The actual, authoritative block against adding an unpriced item is still
        // agAddBtn.disabled (below) + the independent agCurrentRate===null check inside
        // onAddOrUpdateCartItem() — neither of those changes. Manual Rate Override, activated
        // below, is the ONLY other path that can lift this lock, and it carries its own
        // independent authorization gate.
        dom.agWeight.value = '';
        dom.agWeight.disabled = true;
        dom.agQuantity.value = '';
        dom.agQuantity.disabled = true;
        dom.agQtyMinus.disabled = true;
        dom.agQtyPlus.disabled = true;
        dom.agRateOverride.disabled = true;
        dom.agConfiguredRate.disabled = true;
        dom.agTaxDisplay.disabled = true;
        dom.agLineTotalDisplay.disabled = true;
        dom.agAddBtn.disabled = true;
        resetManualOverrideUI();
        manualOverrideConfiguredRate = null;
        if (CAN_MANUAL_OVERRIDE_RATE) { onEnableManualOverrideClick(false); dom.agRateOverride.placeholder = 'Enter price'; }
        // If editing a cart line that was itself saved as an authorized Manual Rate Override,
        // re-activate that state now rather than silently reverting it to locked/offer just
        // because the modal was reopened — preserveRate=true, then explicitly restore the saved
        // rate, since onEnableManualOverrideClick() only skips clearing an already-present value,
        // it doesn't know what to restore on its own.
        if (editingCartIndex !== null && cart[editingCartIndex] && cart[editingCartIndex].manual_override) {
          onEnableManualOverrideClick(true);
          if (restoreOverride !== null && restoreOverride !== undefined) { dom.agRateOverride.value = restoreOverride; }
          recomputeAgLineTotal();
        }
        return;
      }
      dom.agError.classList.add('d-none');
      dom.agAddBtn.disabled = false;
      agCurrentRate = data;

      const isWeight = data.billing_unit === 'weight';
      dom.agBillingUnitDisplay.value = isWeight ? 'Weight (KG)' : 'Quantity (Pieces)';
      dom.agQtyWrap.classList.toggle('d-none', isWeight);
      dom.agWeightWrap.classList.toggle('d-none', !isWeight);
      // Re-enable only the field applicable to this billing unit — the other stays disabled
      // (it's also hidden via the visibility toggle above, this is belt-and-suspenders so its
      // enabled/disabled state is never ambiguous regardless of visibility).
      dom.agWeight.disabled = !isWeight;
      dom.agQuantity.disabled = isWeight;
      dom.agQtyMinus.disabled = isWeight;
      dom.agQtyPlus.disabled = isWeight;
      if (isWeight) { dom.agWeight.value = dom.agWeight.value || ''; } else { dom.agQuantity.value = dom.agQuantity.value || 1; }
      dom.agRateOverride.disabled = false;
      dom.agConfiguredRate.disabled = false;
      dom.agTaxDisplay.disabled = false;
      dom.agLineTotalDisplay.disabled = false;

      const baseRate = isWeight ? data.weight_rate : data.piece_rate;
      const zeroRate = Number(baseRate) === 0;
      dom.agConfiguredRate.value = zeroRate ? 'Price at counter' : fmt(baseRate) + (isWeight ? ' / kg' : ' / pc');
      dom.agRateOverride.value = (restoreOverride !== null && restoreOverride !== undefined) ? restoreOverride : (zeroRate ? '' : baseRate);
      dom.agRateOverride.placeholder = zeroRate ? 'Enter price' : '';
      if (zeroRate) setTimeout(function () { dom.agRateOverride.focus(); }, 200);
      dom.agTaxDisplay.value = data.tax_name ? (data.tax_name + ' ' + data.tax_percent + '%') : 'No tax';
      recomputeAgLineTotal();
      // A configured rate exists, so Manual Rate Override is not forced — but management may
      // still deliberately invoke it (e.g. a special negotiated rate), so the offer stays
      // available as a secondary option rather than hidden entirely.
      resetManualOverrideUI();
      manualOverrideConfiguredRate = fmt(baseRate) + (isWeight ? ' / kg' : ' / pc');
      dom.agManualOverrideOfferRow.classList.remove('d-none');
      // Same re-activation as the failure branch above — a configured rate now existing doesn't
      // change that THIS cart line was specifically saved as an authorized override; that fact
      // must survive reopening the modal to edit it. agRateOverride.value already holds
      // restoreOverride from a few lines up (line ~805), so no re-set is needed here — only
      // preserveRate=true to avoid clearing what's already correctly in place.
      if (editingCartIndex !== null && cart[editingCartIndex] && cart[editingCartIndex].manual_override) {
        onEnableManualOverrideClick(true);
      }
    })
    .catch(function () {
      if (requestId !== agRateRequestSeq) return;
      agCurrentRate = null;
      dom.agError.textContent = 'Could not reach the server to fetch the price. Please try again.';
      dom.agError.classList.remove('d-none');
      resetManualOverrideUI();
      dom.agWeight.value = '';
      dom.agWeight.disabled = true;
      dom.agQuantity.value = '';
      dom.agQuantity.disabled = true;
      dom.agQtyMinus.disabled = true;
      dom.agQtyPlus.disabled = true;
      dom.agRateOverride.value = '';
      dom.agRateOverride.disabled = true;
      dom.agConfiguredRate.value = '';
      dom.agConfiguredRate.disabled = true;
      dom.agTaxDisplay.value = '';
      dom.agTaxDisplay.disabled = true;
      dom.agLineTotalDisplay.value = '';
      dom.agLineTotalDisplay.disabled = true;
      dom.agAddBtn.disabled = true;
    });
}

// DISPLAY-ONLY estimate, updated live as quantity/weight/rate change. The server independently
// recomputes this from PricingEngine + the same rate_override value at submit time — nothing
// here can change what actually gets charged.
function recomputeAgLineTotal() {
  if (!agCurrentRate && !manualOverrideActive) { dom.agLineTotalDisplay.value = ''; return; }
  // isWeight is read from the already-correct visibility toggle rather than agCurrentRate,
  // since agCurrentRate is null during Manual Rate Override on an unpriced garment — the
  // visibility state was still set correctly from billing_unit in both the success AND failure
  // branches of fetchAgRate(), so it remains a reliable signal here regardless of which path led
  // to the modal being in an addable state.
  const isWeight = !dom.agWeightWrap.classList.contains('d-none');
  const rate = parseFloat(dom.agRateOverride.value) || 0;
  let subtotal;
  if (isWeight) {
    const w = parseFloat(dom.agWeight.value) || 0;
    subtotal = w * rate;
    if (!manualOverrideActive && agCurrentRate && agCurrentRate.min_weight_charge && subtotal < agCurrentRate.min_weight_charge) subtotal = agCurrentRate.min_weight_charge;
  } else {
    const q = parseInt(dom.agQuantity.value, 10) || 0;
    subtotal = q * rate;
  }
  dom.agLineTotalDisplay.value = fmt(subtotal);
}

// Resets all three Manual Rate Override UI states to hidden — called before deciding, on every
// fetch resolution and every fresh modal open, which (if any) should actually be shown. Does
// NOT by itself decide whether the offer row should appear — callers do that afterward.
function resetManualOverrideUI() {
  manualOverrideActive = false;
  dom.agManualOverrideOfferRow.classList.add('d-none');
  dom.agManualOverrideUnauthorized.classList.add('d-none');
  dom.agManualOverrideActive.classList.add('d-none');
}

function onEnableManualOverrideClick(preserveRate) {
  dom.agManualOverrideOfferRow.classList.add('d-none');
  if (!CAN_MANUAL_OVERRIDE_RATE) {
    // Client-side gate only — purely informational. The server independently re-checks
    // Auth::can('pos.manual_rate_override') on the actual session at submit time regardless of
    // anything decided here; a person editing this page's JS cannot grant themselves
    // authorization this way.
    dom.agManualOverrideUnauthorized.classList.remove('d-none');
    return;
  }
  manualOverrideActive = true;
  dom.agManualOverrideConfiguredNote.textContent = manualOverrideConfiguredRate
    ? ('Configured rate: ' + manualOverrideConfiguredRate + ' — this override will replace it for this line only.')
    : 'No configured rate exists for this garment/service.';
  dom.agManualOverrideActive.classList.remove('d-none');
  dom.agError.classList.add('d-none');
  // Unlock exactly the fields needed to enter and use the override — billing unit/visibility
  // was already set correctly by fetchAgRate() regardless of which branch led here.
  const isWeight = !dom.agWeightWrap.classList.contains('d-none');
  dom.agWeight.disabled = !isWeight;
  dom.agQuantity.disabled = isWeight;
  dom.agQtyMinus.disabled = isWeight;
  dom.agQtyPlus.disabled = isWeight;
  dom.agRateOverride.disabled = false;
  // preserveRate=true only when re-activating for an edit of an already-saved manual-override
  // cart line (see fetchAgRate()) — fetchAgRate(restoreOverride) already placed that line's own
  // saved rate into this field moments ago; clearing it here would silently discard it.
  if (!preserveRate) { dom.agRateOverride.value = ''; }
  dom.agLineTotalDisplay.disabled = false;
  dom.agAddBtn.disabled = false;
  recomputeAgLineTotal();
}

function onCancelManualOverrideClick() {
  manualOverrideActive = false;
  dom.agManualOverrideActive.classList.add('d-none');
  // Re-run the last fetch's resolution logic by simply re-fetching — the simplest way to return
  // to a guaranteed-correct locked/unlocked state matching whatever is actually configured,
  // rather than trying to hand-reconstruct it here.
  fetchAgRate(null);
}

function onAddOrUpdateCartItem() {
  // Re-entrancy guard: a rapid double-click/double-tap on "Add to Order" fires this handler
  // twice in immediate succession (before the modal has time to close) — without this, that
  // would silently push two identical cart entries for what the user experienced as one click.
  if (dom.agAddBtn.disabled) return;
  if (!agCurrentRate && !manualOverrideActive) { alert('Price not configured for this garment/service — cannot add.'); return; }
  // Defense in depth, matching the same pattern used elsewhere (e.g. stepQuantity()): re-check
  // authorization here too, not just at the button click that activated the override — this is
  // still only a UX guard, the server independently re-verifies regardless.
  if (manualOverrideActive && !CAN_MANUAL_OVERRIDE_RATE) { alert('You are not authorized to use Manual Rate Override.'); return; }
  const isWeight = !dom.agWeightWrap.classList.contains('d-none');
  const qty = parseFloat(dom.agQuantity.value) || 0;
  const weight = parseFloat(dom.agWeight.value) || 0;
  const rateOverride = parseFloat(dom.agRateOverride.value);
  if (!isWeight && qty <= 0) { alert('Quantity must be greater than zero.'); return; }
  if (isWeight && weight <= 0) { alert('Weight must be greater than zero.'); return; }
  if (!manualOverrideActive && agCurrentRate && Number(isWeight ? agCurrentRate.weight_rate : agCurrentRate.piece_rate) === 0 && !(rateOverride > 0)) { alert('This item has no fixed rate. Enter the price.'); return; }
  if (isNaN(rateOverride) || rateOverride < 0) { alert('Rate must be a non-negative number.'); return; }
  if (manualOverrideActive && rateOverride <= 0) { alert('Manual Rate Override requires a rate greater than zero.'); return; }
  dom.agAddBtn.disabled = true;

  // LOCAL, DISPLAY-ONLY estimate so the cart/summary feel instant — the server recomputes this
  // independently (and authoritatively) from PricingEngine + rate_override at submit time.
  let subtotal;
  if (isWeight) {
    subtotal = weight * rateOverride;
    if (!manualOverrideActive && agCurrentRate && agCurrentRate.min_weight_charge && subtotal < agCurrentRate.min_weight_charge) subtotal = agCurrentRate.min_weight_charge;
  } else {
    subtotal = qty * rateOverride;
  }

  const defectIds = Array.from(document.querySelectorAll('.ag-defect:checked')).map(cb => parseInt(cb.value, 10));
  const lineItem = {
    garment_id: pendingGarment.id, garment_name: pendingGarment.name,
    service_id: parseInt(dom.agService.value, 10),
    service_name: dom.agService.selectedOptions[0].textContent,
    billing_unit: isWeight ? 'weight' : 'piece',
    quantity: isWeight ? 1 : qty, weight: isWeight ? weight : null,
    unit: isWeight ? 'Kg' : (pendingGarment.unit || 'Pcs'),
    // Rahul: Quantity (bill lines/units ordered) vs Pieces (physical garments) -- weight mode has
    // no meaningful "pieces per unit" concept, same as it has no tag-per-piece concept.
    pieces_per_unit: isWeight ? 1 : (pendingGarment.pieces_per_unit || 1),
    rate_override: rateOverride,
    manual_override: manualOverrideActive,
    brand_id: dom.agBrand.value || null,
    color_id: dom.agColor.value || null,
    defect_ids: defectIds,
    remarks: dom.agRemarks.value,
    tax_percent: agCurrentRate ? agCurrentRate.tax_percent : 0,
    subtotal: Math.round(subtotal * 100) / 100,
  };

  if (editingCartIndex !== null) {
    cart[editingCartIndex] = lineItem;
  } else {
    cart.push(lineItem);
  }

  editingCartIndex = null;
  agModal.hide();
  renderCart();
}

// ---------- Cart rendering + summary ----------
function renderCart() {
  dom.cartBody.innerHTML = '';
  if (cart.length === 0) {
    dom.cartBody.innerHTML = '<tr><td colspan="4" class="text-muted text-center py-3">No items added yet.</td></tr>';
  } else {
    cart.forEach(function (item, idx) {
      const tr = document.createElement('tr');
      // Rahul: a Set garment shows its physical piece count alongside quantity on each cart
      // line too, e.g. "1 pc x Rs.399.00 (2 pieces)" for a 2-piece Suit -- matches the Pieces
      // total in the summary panel below, line by line.
      const pcsNote = (item.billing_unit !== 'weight' && (item.pieces_per_unit || 1) > 1)
        ? ' (' + (item.quantity * item.pieces_per_unit) + ' pieces)' : '';
      const desc = item.billing_unit === 'weight'
        ? (item.weight + ' kg @ ' + fmt(item.rate_override) + '/kg')
        : (item.quantity + ' pc × ' + fmt(item.rate_override) + pcsNote);
      const overrideBadge = item.manual_override ? ' <span class="badge bg-warning text-dark">MANUAL OVERRIDE</span>' : '';
      tr.innerHTML = '<td>' + (idx + 1) + '/' + cart.length + '</td>'
        + '<td>' + escapeHtml(item.garment_name) + overrideBadge + '<div class="text-muted small">' + escapeHtml(item.service_name) + ' — ' + desc + '</div></td>'
        + '<td class="text-end">' + fmt(item.subtotal) + '</td>'
        + '<td class="text-nowrap">'
        + '<button type="button" class="btn btn-sm btn-outline-primary me-1" data-edit="' + idx + '" title="Edit"><i class="fa-solid fa-pen"></i></button>'
        + '<button type="button" class="btn btn-sm btn-outline-danger" data-remove="' + idx + '" title="Delete"><i class="fa-solid fa-trash"></i></button>'
        + '</td>';
      dom.cartBody.appendChild(tr);
    });
  }
  dom.cartBody.querySelectorAll('[data-edit]').forEach(function (btn) {
    btn.addEventListener('click', function () {
      const idx = parseInt(btn.dataset.edit, 10);
      const item = cart[idx];
      // Reconstruct the minimal garment object openGarmentModal() needs; the rest of the
      // item's saved fields are restored from the cart entry itself inside that function.
      openGarmentModal({ id: item.garment_id, name: item.garment_name, unit: item.unit, default_service_id: item.service_id }, idx);
    });
  });
  dom.cartBody.querySelectorAll('[data-remove]').forEach(function (btn) {
    btn.addEventListener('click', function () {
      cart.splice(parseInt(btn.dataset.remove, 10), 1);
      renderCart();
    });
  });
  recomputeSummary();
}

// Client-side estimate ONLY, for instant on-screen feedback. The authoritative subtotal/
// discount/urgent-charge/tax/grand-total are always computed server-side in
// OrderService::createOrder() from PricingEngine + database configuration — see submitOrder().
function recomputeSummary() {
  // Rahul: Quantity counts ordered units (each cart line's own quantity, piece-mode only --
  // weight-mode lines don't have a meaningful "how many" the same way); Pieces counts physical
  // garments (quantity * pieces_per_unit per line), matching GarmentTagService's own tag count.
  const totalQuantity = cart.reduce((s, i) => s + (i.billing_unit === 'weight' ? 0 : i.quantity), 0);
  const totalPieces = cart.reduce((s, i) => s + (i.billing_unit === 'weight' ? 0 : i.quantity * (i.pieces_per_unit || 1)), 0);
  dom.sumQuantity.textContent = totalQuantity;
  dom.sumPieces.textContent = totalPieces;

  const subtotal = cart.reduce((s, i) => s + i.subtotal, 0);
  const discountType = dom.discountType.value;
  const discountValue = parseFloat(dom.discountValue.value) || 0;
  const discountAmount = discountType === 'Percent'
    ? subtotal * Math.min(discountValue, 100) / 100
    : Math.min(discountValue, subtotal);

  const surchargePct = dom.urgentLevel.value
    ? (parseFloat(dom.urgentLevel.selectedOptions[0].dataset.surcharge) || 0)
    : 0;
  const urgentCharge = (subtotal - discountAmount) * surchargePct / 100;
  const taxableBase = subtotal - discountAmount + urgentCharge;

  let taxAmount = 0;
  cart.forEach(function (item) {
    const share = subtotal > 0 ? (item.subtotal / subtotal) : 0;
    taxAmount += (taxableBase * share) * (item.tax_percent || 0) / 100;
  });

  const deliveryChargeAmount = dom.homeDelivery.checked ? (parseFloat(dom.deliveryCharge.value) || 0) : 0;
  const grandTotal = taxableBase + taxAmount + deliveryChargeAmount;

  dom.sumSubtotal.textContent = fmt(subtotal);
  dom.sumDiscount.textContent = fmt(discountAmount);
  dom.sumUrgent.textContent = fmt(urgentCharge);
  dom.sumDelivery.textContent = fmt(deliveryChargeAmount);
  dom.sumTax.textContent = fmt(taxAmount);
  dom.sumGrandTotal.textContent = fmt(grandTotal);

  updatePaymentSummary(grandTotal);
  return { subtotal, discountAmount, urgentCharge, taxAmount, deliveryCharge: deliveryChargeAmount, grandTotal };
}

function toggleDeliveryCharge() {
  dom.deliveryChargeWrap.classList.toggle('d-none', !dom.homeDelivery.checked);
}

// Computes a SUGGESTED due date from the currently-selected urgent level's day_offset (or the
// 'default_due_days' admin setting when "Normal" is selected — see the data-day-offset attribute
// rendered server-side on each <option>, never a hardcoded number in JS). This only ever fills
// the field automatically; the moment the staff member edits Due Date directly
// (dueDateManuallyEdited becomes true), this function stops overwriting it. The actual value
// submitted is always whatever is currently in the Due Date input, never recomputed silently.
function suggestDueDate() {
  if (dueDateManuallyEdited && dom.dueDate.value) return;
  const opt = dom.urgentLevel.selectedOptions[0];
  const offsetDays = opt ? parseInt(opt.dataset.dayOffset, 10) || 0 : 0;
  const target = new Date();
  target.setDate(target.getDate() + offsetDays);
  const yyyy = target.getFullYear();
  const mm = String(target.getMonth() + 1).padStart(2, '0');
  const dd = String(target.getDate()).padStart(2, '0');
  dom.dueDate.value = yyyy + '-' + mm + '-' + dd;
  dom.dueDateHint.textContent = 'Suggested (' + offsetDays + ' day' + (offsetDays === 1 ? '' : 's') + ' from today, based on ' + (opt ? opt.textContent.trim() : 'Normal') + ') — you can change this.';
}

// ---------- Payment rows ----------
function addPaymentRow(typeId, amount) {
  const row = document.createElement('div');
  row.className = 'row g-2 mb-2 payment-row';
  const options = PAYMENT_TYPES.map(function (pt) {
    return '<option value="' + pt.id + '"' + (typeId == pt.id ? ' selected' : '') + '>' + escapeHtml(pt.type_name) + '</option>';
  }).join('');
  row.innerHTML = '<div class="col-7"><select class="form-select form-select-sm pay-type">' + options + '</select></div>'
    + '<div class="col-4"><input type="number" class="form-control form-control-sm pay-amount" min="0" step="0.01" value="' + (amount || '') + '"></div>'
    + '<div class="col-1"><button type="button" class="btn btn-sm btn-outline-danger remove-pay-row"><i class="fa-solid fa-xmark"></i></button></div>';
  dom.paymentRows.appendChild(row);
  row.querySelector('.pay-amount').addEventListener('input', function () {
    // Only the FIRST payment row is auto-managed by the wallet suggestion logic (matches every
    // example in the spec, which always auto-fills a single "remaining amount" line). Editing
    // any OTHER row is always just a normal manual entry and never flips this flag.
    if (row === dom.paymentRows.querySelector('.payment-row')) paymentManuallyEdited = true;
    updatePaymentSummary();
  });
  row.querySelector('.remove-pay-row').addEventListener('click', function () { row.remove(); updatePaymentSummary(); });
}

// Applies the Advance/Wallet auto-calculation rules:
//   walletToUse = MIN(grandTotal, walletAvailable)          — never exceeds either limit
//   remainingPayment = MAX(0, grandTotal - walletToUse)     — pre-filled into the first payment line
// A manual edit to EITHER field (tracked via walletManuallyEdited / paymentManuallyEdited) stops
// this function from overwriting that specific field going forward — it only re-clamps the
// wallet amount if a later grand-total change would otherwise put it over the allowed maximum.
// Called every time updatePaymentSummary() runs, i.e. on every grand-total-affecting change
// (cart, discount, urgent level, delivery charge) AND on every direct wallet/payment edit.
function applyWalletSuggestion(grandTotal) {
  if (!dom.useWallet.checked) return;

  const maxWallet = Math.max(0, Math.min(grandTotal, walletAvailableAmount));
  dom.walletAmount.max = maxWallet.toFixed(2);

  if (!walletManuallyEdited) {
    dom.walletAmount.value = maxWallet > 0 ? maxWallet.toFixed(2) : '';
  } else {
    // A manually-typed value must NEVER exceed MIN(grandTotal, walletAvailable), even if the
    // grand total just dropped (e.g. an item was removed) — automatically cap it rather than
    // merely warn, per the spec's stated preference.
    const currentWallet = parseFloat(dom.walletAmount.value) || 0;
    if (currentWallet > maxWallet + 0.001) {
      dom.walletAmount.value = maxWallet > 0 ? maxWallet.toFixed(2) : '';
    }
  }

  const walletUsed = parseFloat(dom.walletAmount.value) || 0;
  const remaining = Math.max(0, grandTotal - walletUsed);
  if (!paymentManuallyEdited) {
    const firstRow = dom.paymentRows.querySelector('.pay-amount');
    if (firstRow) firstRow.value = remaining > 0 ? remaining.toFixed(2) : '';
  }
}

function updatePaymentSummary(grandTotalArg) {
  const grandTotal = grandTotalArg !== undefined
    ? grandTotalArg
    : (parseFloat(dom.sumGrandTotal.textContent.replace(/[^0-9.]/g, '')) || 0);

  applyWalletSuggestion(grandTotal);

  let paid = 0;
  document.querySelectorAll('.pay-amount').forEach(inp => paid += parseFloat(inp.value) || 0);
  if (dom.useWallet.checked) paid += parseFloat(dom.walletAmount.value) || 0;
  dom.sumPaid.textContent = fmt(paid);
  dom.sumDue.textContent = fmt(Math.max(0, grandTotal - paid));
}

// ---------- Confirmation + submission ----------
function openConfirmModal() {
  if (!selectedCustomer) { alert('Please select a customer.'); return; }
  if (cart.length === 0) { alert('Add at least one garment.'); return; }
  if (!dom.dueDate.value) { alert('Please select a Due Date.'); dom.dueDate.focus(); return; }

  const summary = recomputeSummary();
  if (!CAN_OVERRIDE_DISCOUNT) {
    const effPct = summary.subtotal > 0 ? (summary.discountAmount / summary.subtotal * 100) : 0;
    if (effPct > MAX_DISCOUNT + 0.01) {
      alert('This discount exceeds your authorized limit of ' + MAX_DISCOUNT + '%.');
      return;
    }
  }

  let html = '<p><strong>Customer:</strong> ' + escapeHtml(selectedCustomer.name) + ' (' + escapeHtml(selectedCustomer.mobile) + ')</p>';
  html += '<p><strong>Due:</strong> ' + escapeHtml(dom.dueDate.value) + (dom.dueTime.value ? ' at ' + escapeHtml(dom.dueTime.value) : '') + '</p>';
  html += '<table class="table table-sm"><thead><tr><th>#</th><th>Item</th><th class="text-end">Total</th></tr></thead><tbody>';
  cart.forEach(function (item, idx) {
    html += '<tr><td>' + (idx + 1) + '/' + cart.length + '</td><td>' + escapeHtml(item.garment_name) + ' — ' + escapeHtml(item.service_name) + '</td><td class="text-end">' + fmt(item.subtotal) + '</td></tr>';
  });
  html += '</tbody></table>';
  html += '<table class="table table-sm">'
    + '<tr><td>Subtotal</td><td class="text-end">' + fmt(summary.subtotal) + '</td></tr>'
    + '<tr><td>Discount</td><td class="text-end">' + fmt(summary.discountAmount) + '</td></tr>'
    + '<tr><td>Urgent Charge</td><td class="text-end">' + fmt(summary.urgentCharge) + '</td></tr>'
    + '<tr><td>Delivery Charge</td><td class="text-end">' + fmt(summary.deliveryCharge) + '</td></tr>'
    + '<tr><td>Tax</td><td class="text-end">' + fmt(summary.taxAmount) + '</td></tr>'
    + '<tr class="fw-bold"><td>Grand Total</td><td class="text-end">' + fmt(summary.grandTotal) + '</td></tr>'
    + '<tr><td>Amount Paid</td><td class="text-end">' + dom.sumPaid.textContent + '</td></tr>'
    + '<tr><td>Current Due</td><td class="text-end">' + dom.sumDue.textContent + '</td></tr>'
    + '</table>';
  dom.confirmBody.innerHTML = html;
  confirmModal.show();
}

// Sends only garment/service/quantity/weight/mode/discount-request/urgent-selection/payment
// lines to the server — never a price, tax, or total. OrderService::createOrder() looks up
// every rate itself via PricingEngine and recomputes discount/urgent/tax/delivery/grand-total
// from scratch, so nothing submitted here can influence what the customer is actually charged.
function submitOrder() {
  if (submitting) return;
  submitting = true;
  dom.confirmSaveBtn.disabled = true;
  dom.confirmSaveBtn.textContent = 'Saving...';

  // Open the new tab SYNCHRONOUSLY, right here in the click handler, BEFORE any async work
  // starts — this is the only reliable way to avoid the browser's popup blocker, which requires
  // window.open() to happen directly inside a user-gesture event handler. The tab starts blank;
  // once the order is confirmed saved (below), we redirect this already-open tab's location to
  // the existing tags_print.php page. If the browser blocks even this synchronous popup,
  // printTab is null and we simply skip the auto-open — the order still saves normally, and
  // "Print/Reprint Tags" on the Order Detail page remains the manual fallback.
  const printTab = window.open('', '_blank');

  const payments = [];
  document.querySelectorAll('.payment-row').forEach(function (row) {
    const amt = parseFloat(row.querySelector('.pay-amount').value) || 0;
    if (amt > 0) payments.push({ payment_type_id: row.querySelector('.pay-type').value, amount: amt });
  });
  const walletAmountValue = dom.useWallet.checked ? (parseFloat(dom.walletAmount.value) || 0) : 0;

  const payload = {
    order_token: orderToken,
    customer_id: selectedCustomer.id,
    price_list_id: selectedPriceListId,
    items: cart.map(function (i) {
      return {
        garment_id: i.garment_id, service_id: i.service_id, quantity: i.quantity, weight: i.weight,
        unit: i.unit, rate_override: i.rate_override, manual_override: !!i.manual_override, brand_id: i.brand_id, color_id: i.color_id,
        defect_ids: i.defect_ids, remarks: i.remarks,
      };
    }),
    urgent_level_id: dom.urgentLevel.value || null,
    due_date: dom.dueDate.value,
    due_time: dom.dueTime.value || null,
    discount_type: dom.discountType.value,
    discount_value: parseFloat(dom.discountValue.value) || 0,
    home_delivery: dom.homeDelivery.checked,
    delivery_charge: parseFloat(dom.deliveryCharge.value) || 0,
    notes: dom.orderNotes.value,
    packaging_preference: dom.packagingPreference.value || null,
    payments: payments,
    wallet_amount: walletAmountValue,
  };

  udcPost(API.submit, payload)
    .then(function (res) {
      if (res.success) {
        // Redirect the already-open (blank) tab to the EXISTING tags_print.php — same page,
        // same QR generation, same layout used by the manual "Print Tags" button; only the
        // order_id + auto_print flag are new. This is not subject to popup blocking since the
        // tab/window already exists.
        if (printTab) {
          printTab.location.href = TAGS_PRINT_URL + '?order_id=' + res.order_id + '&auto_print=1';
        }
        // Same 3-output pattern as the Laundry flow (modules/laundry/index.php) — Invoice +
        // WhatsApp opened here; tags already handled by printTab above.
        // Rahul: WhatsApp confirmation now sends automatically (direct Meta) from
        // OrderService::createOrder() itself -- no more manual wa.me popup here.
        window.open(${j(u('modules/orders/invoice.php'))} + '?id=' + res.order_id, '_blank');
        closeConfirmModalThenRun(function () {
          resetPosForNextOrder(res.order_number || res.order_id);
        });
        return;
      }
      if (printTab) printTab.close();
      alert((res.errors || [res.message || 'Could not save order.']).join('\\n'));
      resetSubmitButton();
    })
    .catch(function () {
      if (printTab) printTab.close();
      alert('Network error — please check your connection and try again.');
      resetSubmitButton();
    });
}

function resetSubmitButton() {
  submitting = false;
  dom.confirmSaveBtn.disabled = false;
  dom.confirmSaveBtn.textContent = 'Confirm & Save';
}

// Called only after a successful save, so the main POS tab stays on the SAME page (never
// navigates away) and is immediately ready for the next customer/order — the tag print tab is a
// separate, already-open tab handled entirely by submitOrder() above.
function resetPosForNextOrder(orderNumberOrId) {
  // Keep the form locked (submitting stays true, button stays disabled/"Saving...") until a
  // FRESH order_token is actually in hand — this closes the exact window where a stale,
  // already-consumed token could be resubmitted for what the staff member intends as a
  // brand-new order. The just-consumed token belonged only to the order that was just saved.
  fetch(API.newOrderToken)
    .then(r => r.json())
    .then(function (data) {
      if (data.success && data.order_token) {
        orderToken = data.order_token;
      } else {
        alert('Order ' + orderNumberOrId + ' was created successfully, but a new security token could not be issued for the next order. Please refresh this page before creating another order.');
      }
      finishResetPosForNextOrder(orderNumberOrId);
    })
    .catch(function () {
      alert('Order ' + orderNumberOrId + ' was created successfully, but a new security token could not be issued for the next order (network error). Please refresh this page before creating another order.');
      finishResetPosForNextOrder(orderNumberOrId);
    });
}

function finishResetPosForNextOrder(orderNumberOrId) {
  resetSubmitButton();
  cart = [];
  renderCart();
  clearCustomer();
  dom.discountValue.value = 0;
  dom.urgentLevel.value = '';
  dom.homeDelivery.checked = false;
  toggleDeliveryCharge();
  dom.orderNotes.value = '';
  dueDateManuallyEdited = false;
  suggestDueDate();
  dom.paymentRows.innerHTML = '';
  addPaymentRow();
  dom.useWallet.checked = false;
  dom.walletAmount.classList.add('d-none');
  dom.walletAmount.value = '';
  recomputeSummary();
  alert('Order ' + orderNumberOrId + ' created successfully. Garment tags opened in a new tab.');
}

// ---------- Small helpers ----------
function fmt(n) { return 'Rs. ' + (Math.round((n || 0) * 100) / 100).toFixed(2); }
function escapeHtml(s) { const d = document.createElement('div'); d.textContent = s || ''; return d.innerHTML; }

/* =====================================================================
 * 7. INITIAL PAGE INITIALIZATION
 * ===================================================================== */
addPaymentRow(); // seed one blank payment line so the payment section is never empty
suggestDueDate(); // pre-fill Due Date with a visible, editable suggestion — never silent
if (PRESELECT_CUSTOMER_ID) {
  selectCustomer(PRESELECT_CUSTOMER_ID);
}

}); // end DOMContentLoaded
</script>`;
export const laundryPickerScript = (u: (p: string) => string, j: (v: unknown) => string, h: (v: unknown) => string, a: Record<string, unknown> = {}, x: string[] = []): string => `    <script>
    // Same api/customers_search.php endpoint already used by modules/pos/index.php — reused
    // directly, not a new search implementation. Selecting a result reloads this page with
    // customer_id set, rather than replicating POS's full rich customer-details card, which this
    // page doesn't need (the customer summary shown once selected is intentionally simple).
    function lwEscapeHtml(s) { const d = document.createElement('div'); d.textContent = s || ''; return d.innerHTML; }
    document.addEventListener('DOMContentLoaded', function () {
      const searchInput = document.getElementById('lwCustomerSearch');
      const resultsBox = document.getElementById('lwCustomerResults');
      let debounceTimer;
      searchInput.addEventListener('input', function () {
        clearTimeout(debounceTimer);
        const q = searchInput.value.trim();
        if (q.length < 2) { resultsBox.classList.add('d-none'); return; }
        debounceTimer = setTimeout(function () {
          fetch(${j(u('api/customers_search.php'))} + '?q=' + encodeURIComponent(q))
            .then(function (r) { return r.json(); })
            .then(function (data) {
              resultsBox.innerHTML = '';
              (data.results || []).forEach(function (c) {
                const div = document.createElement('div');
                div.className = 'p-2 border-bottom';
                div.style.cursor = 'pointer';
                // Shows Name/Mobile/Address/Customer Code — customers_search.php already returns
                // address/area/city/state/pincode; this just displays them, matching the same
                // presentation used on the Landing Page and Per-Piece POS search.
                const addressParts = [c.address, c.area, c.city, c.state, c.pincode].filter(p => p && String(p).trim());
                const addressLine = addressParts.length ? addressParts.join(', ') : '';
                div.innerHTML = '<div class="fw-bold small">' + lwEscapeHtml(c.title + ' ' + c.full_name) + '</div>'
                  + '<div class="small text-muted">Mobile: ' + lwEscapeHtml(c.mobile || '—') + '</div>'
                  + (addressLine ? '<div class="small text-muted">Address: ' + lwEscapeHtml(addressLine) + '</div>' : '')
                  + '<div class="small text-muted">Code: ' + lwEscapeHtml(c.customer_code || '—') + '</div>';
                div.addEventListener('click', function () {
                  window.location.href = ${j(u('modules/laundry/index.php'))} + '?customer_id=' + c.id;
                });
                resultsBox.appendChild(div);
              });
              resultsBox.classList.toggle('d-none', (data.results || []).length === 0);
            })
            .catch(function () { resultsBox.classList.add('d-none'); });
        }, 300);
      });
    });
    </script>`;
