// x[0] = <?= json_encode($laundryOrderToken) ?>
// x[1] = <?= !empty($laundryServices) ? (int)$laundryServices[0]['id'] : 'null' ?>
// x[2] = <?= json_encode(!empty($categories) ? $categories[0]['id'] : null) ?>
// x[3] = <?= json_encode(!empty($categories) ? $categories[0]['id'] : null) ?>
// x[4] = <?= (int)$customer['id'] ?>
export const laundryScript = (u: (p: string) => string, j: (v: unknown) => string, h: (v: unknown) => string, a: Record<string, unknown> = {}, x: string[] = []): string => `<script>
/* =====================================================================
 * Wrapped in DOMContentLoaded, matching modules/pos/index.php's exact same pattern —
 * this inline script tag is rendered BEFORE includes/footer.php's
 * <script src="bootstrap.bundle.min.js"> in document order, so \`bootstrap\` does not exist yet
 * if this code ran immediately. Without this wrapper, \`new bootstrap.Modal(...)\` below throws
 * a ReferenceError that silently halts the rest of this script — which is exactly why
 * "Garment Details" (and every other button here) previously did nothing: the click listeners
 * declared after that line never got attached at all.
 * ===================================================================== */
document.addEventListener('DOMContentLoaded', function () {
const API = {
  garments: ${j(u('api/garments_for_pos.php'))},
  submit: ${j(u('modules/laundry/submit.php'))},
  universalRate: ${j(u('api/pos_get_universal_rate.php'))},
};
const LAUNDRY_ORDER_TOKEN = ${x[0]};
const PRICE_LIST_ID = ${a.priceListId};
let activeServiceId = ${x[1]};
let activeLgCategoryId = null;
let lgSelections = {}; // garment_id -> {name, qty}
let cart = []; // array of {service_id, service_name, weight, rate, garment_count, garments:[{garment_id,name,qty}]}

function fmt(n) { return '₹' + (Math.round((n || 0) * 100) / 100).toFixed(2); }

// Auto-prefills Rate/Kg from price_list_service_rates (via the SAME endpoint already built for
// POS's Common Laundry Services panel — no rate logic duplicated here) whenever the selected
// service or price list changes. The field stays fully editable afterward — this only sets an
// initial value, it never locks the input or overrides a manual edit after the fact.
function fetchUniversalRate(serviceId) {
  if (!serviceId) return;
  fetch(API.universalRate + '?service_id=' + encodeURIComponent(serviceId) + '&price_list_id=' + encodeURIComponent(PRICE_LIST_ID))
    .then(function (r) { return r.json(); })
    .then(function (data) {
      if (data.success) {
        document.getElementById('lbRate').value = data.weight_rate;
      } else {
        // No configured rate — leave the field blank rather than silently showing/keeping a
        // stale or fabricated number; Add to Cart validation below still requires a real value.
        document.getElementById('lbRate').value = '';
      }
      recomputeEstimate();
    })
    .catch(function () {
      document.getElementById('lbRate').value = '';
      recomputeEstimate();
    });
}

document.querySelectorAll('.laundry-svc-tab').forEach(function (btn) {
  btn.addEventListener('click', function () {
    document.querySelectorAll('.laundry-svc-tab').forEach(function (b) { b.classList.remove('active', 'btn-primary'); b.classList.add('btn-outline-primary'); });
    this.classList.remove('btn-outline-primary'); this.classList.add('active', 'btn-primary');
    activeServiceId = parseInt(this.dataset.id, 10);
    fetchUniversalRate(activeServiceId);
  });
});
// Prefill immediately for the default-selected tab (Wash N Iron) on page load — the operator
// should never have to click the already-selected tab just to see its rate populate.
fetchUniversalRate(activeServiceId);

function recomputeEstimate() {
  const w = parseFloat(document.getElementById('lbWeight').value) || 0;
  const r = parseFloat(document.getElementById('lbRate').value) || 0;
  document.getElementById('lbEstimate').value = fmt(w * r);
}
document.getElementById('lbWeight').addEventListener('input', recomputeEstimate);
document.getElementById('lbRate').addEventListener('input', recomputeEstimate);

// ---------- Garment Details modal ----------
const gdModal = new bootstrap.Modal(document.getElementById('garmentDetailsModal'));
document.getElementById('lbGarmentDetailsBtn').addEventListener('click', function () {
  gdModal.show();
  if (!activeLgCategoryId && ${x[2]}) {
    activeLgCategoryId = ${x[3]};
  }
  loadLgGarments();
  renderLgSelected();
});

document.querySelectorAll('.lg-cat-tab').forEach(function (btn) {
  btn.addEventListener('click', function () {
    activeLgCategoryId = parseInt(this.dataset.id, 10);
    document.querySelectorAll('.lg-cat-tab').forEach(function (b) { b.classList.remove('btn-secondary'); b.classList.add('btn-outline-secondary'); });
    this.classList.remove('btn-outline-secondary'); this.classList.add('btn-secondary');
    loadLgGarments();
  });
});

function loadLgGarments() {
  const params = new URLSearchParams({ category_id: activeLgCategoryId || '', service_id: activeServiceId || '' });
  fetch(API.garments + '?' + params.toString())
    .then(function (r) { return r.json(); })
    .then(function (data) {
      const grid = document.getElementById('lgGrid');
      grid.innerHTML = (data.garments || []).map(function (g) {
        return '<div class="lg-card" data-id="' + g.id + '" data-name="' + g.name.replace(/"/g, '&quot;') + '"><div>' + g.name + '</div></div>';
      }).join('');
      grid.querySelectorAll('.lg-card').forEach(function (card) {
        card.addEventListener('dblclick', function () {
          const id = this.dataset.id, name = this.dataset.name;
          if (!lgSelections[id]) lgSelections[id] = { name: name, qty: 1 }; else lgSelections[id].qty++;
          renderLgSelected();
        });
      });
    });
}

function renderLgSelected() {
  const wrap = document.getElementById('lgSelected');
  const ids = Object.keys(lgSelections);
  wrap.innerHTML = ids.map(function (id) {
    const s = lgSelections[id];
    return '<div class="lg-sel-card" data-id="' + id + '"><span class="lg-qty-badge">' + s.qty + '</span><div>' + s.name + '</div>'
      + '<div class="lg-steppers"><button type="button" class="btn btn-sm btn-outline-secondary lg-minus">-</button><button type="button" class="btn btn-sm btn-outline-secondary lg-plus">+</button></div></div>';
  }).join('');
  let total = 0;
  ids.forEach(function (id) { total += lgSelections[id].qty; });
  document.getElementById('lgTotalSelected').textContent = total;
  wrap.querySelectorAll('.lg-minus').forEach(function (b) {
    b.addEventListener('click', function () {
      const id = this.closest('.lg-sel-card').dataset.id;
      lgSelections[id].qty = Math.max(0, lgSelections[id].qty - 1);
      if (lgSelections[id].qty === 0) delete lgSelections[id];
      renderLgSelected();
    });
  });
  wrap.querySelectorAll('.lg-plus').forEach(function (b) {
    b.addEventListener('click', function () {
      const id = this.closest('.lg-sel-card').dataset.id;
      lgSelections[id].qty++;
      renderLgSelected();
    });
  });
}

document.getElementById('lgContinueBtn').addEventListener('click', function () {
  const declared = parseInt(document.getElementById('lbGarmentCount').value, 10) || 0;
  let selectedTotal = 0;
  Object.values(lgSelections).forEach(function (s) { selectedTotal += s.qty; });
  if (selectedTotal !== declared) {
    document.getElementById('qtyMismatchText').textContent =
      'You have provided information for ' + selectedTotal + ' garments, however the batch quantity is ' + declared + ' garments.';
    new bootstrap.Modal(document.getElementById('qtyMismatchModal')).show();
    return;
  }
  gdModal.hide();
  updateGarmentSummary();
});

document.getElementById('qtyMismatchVerify').addEventListener('click', function () {
  bootstrap.Modal.getInstance(document.getElementById('qtyMismatchModal')).hide();
});

function updateGarmentSummary() {
  const parts = Object.values(lgSelections).map(function (s) { return s.name + ' × ' + s.qty; });
  document.getElementById('lbGarmentSummary').textContent = parts.length ? parts.join(', ') : 'No garments identified yet.';
}

// ---------- Add to Cart ----------
document.getElementById('lbAddToCartBtn').addEventListener('click', function () {
  const weight = parseFloat(document.getElementById('lbWeight').value) || 0;
  const rate = parseFloat(document.getElementById('lbRate').value) || 0;
  const garmentCount = parseInt(document.getElementById('lbGarmentCount').value, 10) || 0;
  const svcBtn = document.querySelector('.laundry-svc-tab.active');
  if (weight <= 0) { alert('Weight must be greater than zero.'); return; }
  if (rate <= 0) { alert('Rate per KG must be greater than zero.'); return; }
  if (garmentCount <= 0) { alert('Number of garments must be greater than zero.'); return; }
  let selectedTotal = 0;
  Object.values(lgSelections).forEach(function (s) { selectedTotal += s.qty; });
  if (selectedTotal !== garmentCount) {
    alert('Identified garments (' + selectedTotal + ') do not match the declared garment count (' + garmentCount + '). Use Garment Details to verify.');
    return;
  }
  const garments = Object.keys(lgSelections).map(function (id) {
    return { garment_id: parseInt(id, 10), name: lgSelections[id].name, quantity: lgSelections[id].qty };
  });
  cart.push({
    service_id: parseInt(svcBtn.dataset.id, 10), service_name: svcBtn.textContent.trim(),
    weight: weight, rate: rate, garment_count: garmentCount, garments: garments,
  });
  lgSelections = {};
  document.getElementById('lbWeight').value = '';
  document.getElementById('lbGarmentCount').value = '';
  document.getElementById('lbEstimate').value = '';
  // Re-fetch the CONFIGURED universal rate for the still-selected service, rather than blanking
  // the field — the operator's next batch should start from the real price-list rate, not
  // require re-entering it, and this also correctly resets away from a manual edit made for the
  // PREVIOUS batch (which itself is already safely captured in cart.push() above, unaffected by
  // this reset — only the FORM field changes, not the batch already added to the cart array).
  fetchUniversalRate(activeServiceId);
  updateGarmentSummary();
  renderCart();
});

function renderCart() {
  const list = document.getElementById('cartList');
  if (!cart.length) {
    list.innerHTML = '<p class="text-muted small">No batches added yet.</p>';
    document.getElementById('checkoutBtn').disabled = true;
  } else {
    list.innerHTML = cart.map(function (b, i) {
      const garmentsDesc = b.garments.map(function (g) { return g.name + ' × ' + g.quantity; }).join(', ');
      return '<div class="laundry-batch-line"><div class="d-flex justify-content-between"><strong>' + b.service_name + '</strong>'
        + '<button type="button" class="btn btn-sm btn-outline-danger" onclick="removeCartLine(' + i + ')">&times;</button></div>'
        + '<div class="small text-muted">' + b.weight + ' kg × ' + fmt(b.rate) + '/kg = ' + fmt(b.weight * b.rate) + '</div>'
        + '<div class="small text-muted">' + b.garment_count + ' garments: ' + garmentsDesc + '</div></div>';
    }).join('');
    document.getElementById('checkoutBtn').disabled = false;
  }
  let totalWeight = 0, totalGarments = 0, totalAmount = 0;
  cart.forEach(function (b) { totalWeight += b.weight; totalGarments += b.garment_count; totalAmount += b.weight * b.rate; });
  document.getElementById('cartTotalWeight').textContent = totalWeight.toFixed(2) + ' KG';
  document.getElementById('cartTotalGarments').textContent = totalGarments;
  document.getElementById('cartTotalAmount').textContent = fmt(totalAmount);
}
function removeCartLine(i) { cart.splice(i, 1); renderCart(); }

// ---------- Checkout ----------
const checkoutModal = new bootstrap.Modal(document.getElementById('checkoutModal'));
document.getElementById('checkoutBtn').addEventListener('click', function () {
  const d = new Date(); d.setDate(d.getDate() + 2);
  document.getElementById('coDueDate').value = d.toISOString().slice(0, 10);
  recomputeCheckoutSummary();
  checkoutModal.show();
});
['coDiscountType', 'coDiscountValue', 'coDeliveryCharge', 'coHomeDelivery'].forEach(function (id) {
  document.getElementById(id).addEventListener('input', recomputeCheckoutSummary);
  document.getElementById(id).addEventListener('change', recomputeCheckoutSummary);
});
function recomputeCheckoutSummary() {
  let subtotal = 0;
  cart.forEach(function (b) { subtotal += b.weight * b.rate; });
  const discType = document.getElementById('coDiscountType').value;
  const discVal = parseFloat(document.getElementById('coDiscountValue').value) || 0;
  const discount = discType === 'Percent' ? subtotal * Math.min(discVal, 100) / 100 : Math.min(discVal, subtotal);
  const delivery = document.getElementById('coHomeDelivery').checked ? (parseFloat(document.getElementById('coDeliveryCharge').value) || 0) : 0;
  const grand = subtotal - discount + delivery;
  document.getElementById('coSummary').innerHTML =
    '<div class="d-flex justify-content-between"><span>Subtotal</span><span>' + fmt(subtotal) + '</span></div>'
    + '<div class="d-flex justify-content-between"><span>Discount</span><span>' + fmt(discount) + '</span></div>'
    + '<div class="d-flex justify-content-between"><span>Delivery</span><span>' + fmt(delivery) + '</span></div>'
    + '<div class="d-flex justify-content-between fw-bold"><span>Grand Total</span><span>' + fmt(grand) + '</span></div>';
}

document.getElementById('saveOrderBtn').addEventListener('click', function () {
  if (!cart.length) { alert('Add at least one Laundry batch first.'); return; }
  this.disabled = true;
  const advanceAmount = parseFloat(document.getElementById('coAdvanceAmount').value) || 0;
  const payload = {
    customer_id: ${x[4]},
    order_token: LAUNDRY_ORDER_TOKEN,
    batches: cart.map(function (b) {
      return {
        service_id: b.service_id, weight: b.weight, rate: b.rate, garment_count: b.garment_count,
        garments: b.garments.map(function (g) { return { garment_id: g.garment_id, quantity: g.quantity }; }),
      };
    }),
    urgent_level_id: document.getElementById('coUrgent').value || null,
    due_date: document.getElementById('coDueDate').value,
    discount_type: document.getElementById('coDiscountType').value,
    discount_value: parseFloat(document.getElementById('coDiscountValue').value) || 0,
    home_delivery: document.getElementById('coHomeDelivery').checked,
    delivery_charge: parseFloat(document.getElementById('coDeliveryCharge').value) || 0,
    payments: advanceAmount > 0 ? [{ payment_type_id: document.getElementById('coPaymentType').value, amount: advanceAmount }] : [],
  };
  udcPost(API.submit, payload).then(function (res) {
    document.getElementById('saveOrderBtn').disabled = false;
    if (!res.success) { alert((res.errors || ['Could not save the order.']).join('\\n')); return; }
    checkoutModal.hide();
    // Same new-tab-for-tags pattern as the existing POS flow, plus invoice + WhatsApp.
    const tagsTab = window.open('', '_blank');
    tagsTab.location.href = ${j(u('modules/barcode/tags_print.php'))} + '?order_id=' + res.order_id + '&auto_print=1';
    // Rahul: WhatsApp confirmation now sends automatically (direct Meta) from
    // OrderService::createLaundryOrder() itself -- no more manual wa.me popup here.
    // Invoice is the primary redirect destination — Order Details is deliberately not opened
    // after a Laundry save; only Invoice + Tags/QR + WhatsApp, per the approved final flow.
    window.location.href = ${j(u('modules/orders/invoice.php'))} + '?id=' + res.order_id;
  }).catch(function () {
    document.getElementById('saveOrderBtn').disabled = false;
    alert('Could not reach the server. Please try again.');
  });
});
}); // closes document.addEventListener('DOMContentLoaded', ...)
</script>`;
